// Logo cargado dinámicamente
const LOGO_B64 =
  "";
if (
  LOGO_B64 &&
  LOGO_B64 !==
    ""
) {
  const src = "data:image/jpeg;base64," + LOGO_B64;
  document.getElementById("sbLogo").src = src;
  document.getElementById("tbLogo").src = src;
}

