let LOGS = [];
function addLog(ev, det, res = "—") {
  const now = new Date();
  const ts = now.toLocaleTimeString("es-CL", {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
  LOGS.push({ ts, ev, det, res });
  renderLogs();
  updateDirectCreditCta();
  applyHappyBrandLogos();
}
function renderLogs() {
  const el = document.getElementById("logsContent");
  if (!el) return;
  if (!LOGS.length) {
    el.innerHTML =
      '<div style="text-align:center;padding:24px;color:var(--slate4);font-size:13px">Sin registros</div>';
    return;
  }
  el.innerHTML = [...LOGS]
    .reverse()
    .map(
      (l) => `
    <div class="log-row">
      <span class="log-ts">${l.ts}</span>
      <span class="log-ev">${l.ev}</span>
      <span class="log-det">${l.det}</span>
      <span class="${l.res === "OK" ? "log-ok" : l.res === "FAIL" ? "log-fail" : ""}">${l.res}</span>
    </div>`,
    )
    .join("");
}

