const STEPS_DEF = [
  { lbl: "Identificación\n+LDPD" },
  { lbl: "OTP" },
  { lbl: "Evaluación\nAutomática" },
  { lbl: "Oferta" },
  { lbl: "Referencias\n+ Formalización" },
  { lbl: "Contrato\nActivo" },
];
let timerPct = 0,
  timerIv = null;
function setProgress(active) {
  document.getElementById("progressStrip").classList.add("show");
  const el = document.getElementById("psRow");
  let h = "";
  STEPS_DEF.forEach((s, i) => {
    const done = i < active,
      act = i === active;
    const dc = done ? "done" : act ? "active" : "pend";
    const lc = done ? "done" : act ? "active" : "";
    h += `<div class="ps-item ${done ? "done" : ""}">
      <div class="ps-wrap">
        <div class="ps-dot ${dc}">${done ? "✓" : i + 1}</div>
        <div class="ps-lbl ${lc}">${s.lbl.replace("\n", "<br>")}</div>
      </div>
    </div>`;
    if (i < STEPS_DEF.length - 1)
      h += `<div class="ps-item" style="flex:0.6;padding-top:11px"><div style="height:2px;background:${done ? "var(--lime)" : "var(--slate2)"};width:100%;border-radius:2px;transition:background .3s"></div></div>`;
  });
  el.innerHTML = h;
}
function startTimer() {
  timerPct = 0;
  clearInterval(timerIv);
  timerIv = setInterval(() => {
    timerPct = Math.min(timerPct + 100 / 300, 100); // 300s = 5 min
    document.getElementById("psTimerFill").style.width = timerPct + "%";
  }, 1000);
}
function stopTimer() {
  clearInterval(timerIv);
}
function hideProgress() {
  document.getElementById("progressStrip").classList.remove("show");
  document.getElementById("psTimerFill").style.width = "0%";
  stopTimer();
}

