function clp(n) {
  return (
    "US$" +
    Number(n || 0).toLocaleString("en-US", {
      maximumFractionDigits: 0,
    })
  );
}
function rutDigits(value) {
  return String(value || "").replace(/\D/g, "");
}
function getDemoPrecalificacion() {
  const rut = rutDigits(S.rut);
  if (S.demoPrecalificacion) {
    return {
      ...S.demoPrecalificacion,
      identificacion: rut || S.demoPrecalificacion.identificacion,
      nombre: S.nombre || S.demoPrecalificacion.nombre,
    };
  }
  const found = PRECALIFICACIONES_DEMO.find((p) => p.identificacion === rut);
  if (found) return { ...found };
  const ing = Number(S.ingresos || 0);
  const gast = Number(S.gastos || 0);
  const disponibleBase = ing > 0 ? ing - gast : 300;
  if (disponibleBase === 300) {
    const rotating = [300, 400, 500, 600]
      .map((cupo) => PRECALIFICACIONES_DEMO.find((p) => p.cupo === cupo))
      .filter(Boolean);
    const demo = rotating[DEMO_PRECAL_TURN % rotating.length];
    DEMO_PRECAL_TURN++;
    return {
      ...demo,
      identificacion: rut || demo.identificacion,
      nombre: S.nombre || demo.nombre,
      ticket: Number(new Date().toISOString().replace(/\D/g, "").slice(0, 14)),
    };
  }
  const disponible = Math.max(220, Math.min(700, Math.round(disponibleBase)));
  let entrada = 30;
  let plazo = "13-26";
  let perfil = "F3";
  if (disponible >= 450) {
    entrada = 20;
    plazo = "13-18-26-33";
    perfil = "F1";
  } else if (disponible >= 280) {
    entrada = 25;
    plazo = "13-26-33";
    perfil = "F2";
  }
  return {
    identificacion: rut || S.rut,
    nombre: S.nombre || "CLIENTE LEASING",
    idPerfil: perfil === "F1" ? 21 : perfil === "F2" ? 31 : 41,
    perfil,
    producto: "CELULAR",
    cupo: disponible,
    entrada,
    tipoEntrada: "PORCENTAJE",
    plazo,
    cupoDisponible: disponible,
    ticket: Number(new Date().toISOString().replace(/\D/g, "").slice(0, 14)),
    promocionEntrada: "",
    verificacion: "DFL",
  };
}
function plazosFromPrecal(precal) {
  const allowed = String(precal?.plazo || "")
    .split("-")
    .map((x) => Number(x.trim()))
    .filter(Boolean);
  const result = PLAZOS.filter((p) => allowed.includes(p.sem));
  return result.length ? result : [PLAZOS[0]];
}
function entradaFromPrecal(total, precal) {
  if (!precal) return Math.round(total * 0.14);
  const cupo = Number(precal.cupoDisponible ?? precal.cupo ?? 0);
  const entradaApi = Number(precal.entrada || 0);
  const entradaPorTipo =
    precal.tipoEntrada === "PORCENTAJE"
      ? Math.ceil(total * (entradaApi / 100))
      : Math.ceil(entradaApi);
  const excesoSobreCupo = cupo > 0 ? Math.max(0, total - cupo) : 0;
  return Math.min(total, Math.max(entradaPorTipo, excesoSobreCupo));
}
function fmtRut(el) {
  el.value = el.value.replace(/\D/g, "").slice(0, 10);
  if (el.id === "lp1_rut") validateLp1Field("rut");
}
function fmtTel(el) {
  let digits = el.value.replace(/\D/g, "");
  if (digits.startsWith("593")) digits = digits.slice(3);
  digits = digits.replace(/^0+/, "");
  if (digits && !digits.startsWith("9")) digits = "9" + digits;
  digits = digits.slice(0, 9);
  let v = digits;
  if (digits.length > 0) v = "+593 " + digits.slice(0, 2);
  if (digits.length > 2) v += " " + digits.slice(2, 5);
  if (digits.length > 5) v += " " + digits.slice(5, 9);
  el.value = v;
  if (el.id === "lp1_tel") validateLp1Field("tel");
}

function cleanRut(value) {
  return value.replace(/\D/g, "").trim();
}
function formatRut(value) {
  const clean = cleanRut(value);
  return clean.slice(0, 10);
}
function isValidRut(value) {
  const clean = cleanRut(value);
  return /^\d{10}$/.test(clean);
}
function normalizeEcuadorMobile(value) {
  let digits = value.replace(/\D/g, "");
  if (digits.startsWith("593")) digits = digits.slice(3);
  digits = digits.replace(/^0+/, "");
  if (/^9\d{8}$/.test(digits)) {
    return "+593 " + digits.slice(0, 2) + " " + digits.slice(2, 5) + " " + digits.slice(5);
  }
  return "";
}
const normalizeChileMobile = normalizeEcuadorMobile;
function isValidEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value.trim());
}
function isValidFullName(value) {
  const name = value.trim().replace(/\s+/g, " ");
  const parts = name.split(" ");
  return (
    name.length >= 5 &&
    parts.length >= 2 &&
    parts.every((p) => /^[A-Za-zÁÉÍÓÚÜÑáéíóúüñ'-]{2,}$/.test(p))
  );
}
function getAge(dateValue) {
  const birth = new Date(dateValue + "T00:00:00");
  if (Number.isNaN(birth.getTime())) return null;
  const today = new Date();
  let age = today.getFullYear() - birth.getFullYear();
  const m = today.getMonth() - birth.getMonth();
  if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
  return age;
}
function setFieldState(el, message, touched = true) {
  if (!el) return false;
  let ferr = el.parentElement.querySelector(".ferr");
  if (!ferr) {
    ferr = document.createElement("div");
    ferr.className = "ferr";
    el.insertAdjacentElement("afterend", ferr);
  }
  el.classList.remove("ok", "err");
  ferr.textContent = message || "";
  ferr.style.display = message ? "block" : "none";
  if (touched || el.value.trim()) el.classList.add(message ? "err" : "ok");
  return !message;
}
function validateLp1Field(field, touched = true) {
  const fields = {
    rut: document.getElementById("lp1_rut"),
    nom: document.getElementById("lp1_nom"),
    tel: document.getElementById("lp1_tel"),
    email: document.getElementById("lp1_email"),
    birth: document.getElementById("lp1_birth"),
  };
  const el = fields[field];
  if (!el) return false;
  const value = el.value.trim();
  let message = "";
  if (!value) message = "Campo obligatorio.";
  else if (field === "rut" && !/^\d+$/.test(value))
    message = "La CI debe contener solo numeros.";
  else if (field === "rut" && !isValidRut(value))
    message = "Ingresa una CI de Ecuador de 10 digitos.";
  else if (field === "nom" && !isValidFullName(value))
    message = "Ingresa nombre y apellido, solo letras.";
  else if (field === "tel" && !normalizeEcuadorMobile(value))
    message = "Usa un celular ecuatoriano valido: +593 99 123 4567.";
  else if (field === "email" && !isValidEmail(value))
    message = "Ingresa un correo válido.";
  else if (field === "birth") {
    const age = getAge(value);
    if (age === null) message = "Ingresa una fecha válida.";
    else if (age < 18) message = "El cliente debe tener al menos 18 años.";
    else if (age > 100) message = "Revisa la fecha de nacimiento.";
  }
  return setFieldState(el, message, touched);
}
function validateLp1Form() {
  const results = ["rut", "nom", "tel", "email", "birth"].map((field) =>
    validateLp1Field(field),
  );
  return results.every(Boolean);
}
function parseMoneyInput(value) {
  return parseInt(String(value || "").replace(/\D/g, ""), 10) || 0;
}
function markFieldState(el, message, touched = true) {
  if (!el) return false;
  let ferr = el.parentElement.querySelector(".ferr");
  if (!ferr) {
    ferr = document.createElement("div");
    ferr.className = "ferr";
    el.insertAdjacentElement("afterend", ferr);
  }
  el.classList.remove("ok", "err");
  ferr.textContent = message || "";
  ferr.style.display = message ? "block" : "none";
  if (touched || el.value.trim()) el.classList.add(message ? "err" : "ok");
  return !message;
}

/* ═══════════════════════════════════════════════════
   TOAST
═══════════════════════════════════════════════════ */
function toast(msg, type = "ok") {
  const w = document.getElementById("toasts");
  const t = document.createElement("div");
  t.className = `toast ${type}`;
  const ic = { ok: "✅", err: "❌", warn: "⚠️" };
  t.innerHTML = `<span>${ic[type] || "ℹ️"}</span><span>${msg}</span>`;
  w.appendChild(t);
  setTimeout(() => {
    t.style.transition = "opacity .3s";
    t.style.opacity = "0";
    setTimeout(() => t.remove(), 300);
  }, 3500);
}

