function renderCatalog() {
  updateDirectCreditCta();
  const q = (document.getElementById("searchQ")?.value || "")
    .toLowerCase()
    .trim();
  const brand = catalogSelectValue("filterBrand");
  const price = catalogSelectValue("filterPrice");
  const model = catalogSelectValue("filterModel");
  const gama = catalogSelectValue("filterGama");
  const grid = document.getElementById("prodGrid");
  updateCatalogFilterButton();
  if (!S.catFilter) {
    S.catFilter = "celular";
    syncCatalogTabs("celular");
    syncSidebarCategory("celular");
  }
  const filterKey = [
    S.catFilter,
    q,
    brand,
    price,
    model,
    gama,
  ].join("|");
  if (S.catalogFilterKey !== filterKey) {
    S.catalogFilterKey = filterKey;
    S.catalogPage = 1;
  }
  const list = PRODUCTS.filter((p) => {
    const haystack = [
      p.name,
      p.marca,
      p.modelo,
      p.ram,
      p.rom,
      ...(p.units || []).map((u) => u.imei),
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();
    const priceValue = Number(p.price || 0);
    const gamaMatch =
      !gama ||
      (gama === "baja" && priceValue <= 250) ||
      (gama === "media" && priceValue > 250 && priceValue <= 500) ||
      (gama === "alta" && priceValue > 500);
    const mc =
      S.catFilter === "todos" ||
      p.cat === S.catFilter ||
      (S.catFilter === "recomendado" && p.recomendado);
    return (
      mc &&
      (!brand || p.marca === brand) &&
      matchCatalogPrice(p, price) &&
      (!model || (p.modelo || p.name || "").toLowerCase().includes(model.toLowerCase())) &&
      gamaMatch &&
      (!q || haystack.includes(q))
    );
  });
  if (!list.length) {
    grid.classList.toggle("promo-grid", S.catFilter === "promo");
    grid.innerHTML =
      '<div class="catalog-empty">No hay productos para esos filtros. Ajusta marca, modelo, precio o gama.</div>';
    return;
  }
  grid.classList.toggle("promo-grid", S.catFilter === "promo");
  const pageSize = S.catFilter === "promo" ? 10 : 6;
  const totalPages = Math.ceil(list.length / pageSize);
  S.catalogPage = Math.min(Math.max(Number(S.catalogPage) || 1, 1), totalPages);
  const start = (S.catalogPage - 1) * pageSize;
  const pageItems = list.slice(start, start + pageSize);
  grid.innerHTML =
    renderCompareSelectionBar() +
    renderCategoryShowcase(list) +
    pageItems
      .map((p, idx) => {
        const avail = (p.units || []).filter((u) => u.st === "disponible");
        const nextImei = avail[0]?.imei;
        const inCart = S.cart.find((x) => x.id === p.id);
        const eligible = p.cat === "celular";
        const selectedForCompare = productosComparados.some(
          (x) => String(x.id) === String(p.id),
        );
        const catLabel =
          p.cat === "celular"
            ? "Celular - Elegible leasing"
            : p.cat === "combo"
              ? "Combo comercial"
              : p.cat === "promo"
                ? "Promocion especial"
                : p.cat === "regalo"
                  ? "Regalo para cierre"
                  : "Accesorio";
        const pvpShow = !eligible && p.oldPrice
            ? `<div class="prod-pvp prod-old">Antes ${clp(p.oldPrice)}</div>`
            : "";
        const promoCard = p.cat === "promo";
        const comboCard = p.cat === "combo";
        const comboIncludes = comboCard ? comboIncludedItems(p) : [];
        const comboSave = comboCard
          ? Math.max(20, Math.round(p.price * 0.07))
          : 0;
        const cupo = currentLeasingCupo();
        const cupoInsuficiente =
          S.payMethod === "leasing" && Number(p.price) > cupo;
        return `<div class="prod-card ${promoCard ? "promo-card" : ""} ${comboCard ? "combo-card" : ""} ${cupoInsuficiente ? "cupo-insuficiente" : ""} ${modoComparacion && eligible ? "compare-mode" : ""} ${selectedForCompare ? "is-compare-selected" : ""}" style="--enter-delay:${idx * 45}ms" ${modoComparacion && eligible ? `onclick="seleccionarParaComparar(${p.id})"` : ""}>
      ${promoCard ? `<div class="prod-offer-badge">${p.discount || "Oferta"}</div>` : ""}
      ${comboCard ? `<div class="combo-save-pill">Ahorra ${clp(comboSave)}</div>` : ""}
      <div class="prod-visual">${productImageMarkup(p)}</div>
      <div class="prod-name">${p.name}</div>
      ${p.marca ? `<div class="prod-spec">${p.marca} · ${p.modelo || ""}</div>` : ""}
      ${p.ram ? `<div class="prod-spec" style="color:var(--slate3)">${p.ram} · ${p.rom}</div>` : ""}
      <div class="prod-cat">${catLabel}</div>
      ${promoCard ? `<div class="prod-tags promo-tags"><b>${p.promoTag || "Promo activa"}</b></div>` : p.recomendado ? `<div class="prod-tags"><b>Recomendado</b></div>` : ""}
      ${promoCard && p.desc ? `<div class="prod-promo-desc">${p.desc}</div>` : ""}
      ${comboCard ? `<ul class="combo-includes">${comboIncludes.map((item) => `<li>${item}</li>`).join("")}</ul>` : ""}
      ${pvpShow}
      <div class="prod-price">${clp(p.price)}</div>
      ${modoComparacion && eligible ? `<button class="prod-add prod-compare-pick" type="button" onclick="event.stopPropagation(); seleccionarParaComparar(${p.id})">${selectedForCompare ? "Seleccionado" : "Comparar"}</button>` : ""}
      ${eligible && nextImei ? `<div class="prod-imei-tag" title="IMEI auto-asignado">🔑 ${nextImei}</div>` : ""}
      <div style="margin-bottom:6px">${avail.length > 0 || !eligible ? `<span class="badge b-lime">Stock: ${eligible ? avail.length : p.stock || "✓"}</span>` : `<span class="badge b-red">Sin stock</span>`}</div>
<button 
  class="prod-add ${cupoInsuficiente ? "prod-add-blocked" : ""}" 
  onclick="${cupoInsuficiente ? "return false" : `addCart(${p.id})`}" 
  ${cupoInsuficiente || (eligible && avail.length === 0) ? "disabled" : ""}
>
  ${cupoInsuficiente ? "✕ CUPO INSUFICIENTE" : inCart ? `✓ ${inCart.qty} en carrito` : comboCard ? "+ Agregar combo" : " + Agregar"}
</button>    </div>`;
      })
      .join("") +
    renderCatalogPager(list.length, S.catalogPage, pageSize);
}

