function renderCategoryShowcase(list) {
  const config = {
    promo: {
      title: "Promos activas",
      sub: `${list.length} oportunidades para ofrecer una mejor opcion al cliente`,
      text: "Descuentos - Packs listos - Audio - Proteccion - Accesorios",
    },
    celular: {
      title: "Celulares disponibles",
      sub: `${list.length} equipos para venta a crédito directo`,
      text: "Equipos con IMEI - Diferentes Opciones - Descuentos autorizados - Accesorios sugeridos",
    },
    combo: {
      title: "Combos",
      //sub: `${list.length} paquetes listos para subir el ticket`,
      text: "Packs listos - Audio - Proteccion - Entretenimiento - Ahorro",
    },
    accesorio: {
      title: "Accesorios sugeridos",
      sub: `${list.length} agregados para completar la venta`,
      text: "Audio - Proteccion - Carga - Entretenimiento",
    },
  };
  const cfg = config[S.catFilter];
  if (!cfg) return "";
  const savings = list
    .filter((p) => p.oldPrice)
    .map((p) => Math.max(0, p.oldPrice - p.price))
    .reduce((a, b) => a + b, 0);
  return `<div class="promo-showcase">
    <div>
      <strong>${cfg.title}</strong>
      <span>${cfg.sub}</span>
    </div>
    <div class="promo-marquee" aria-hidden="true">
      <span>${cfg.text} - Ahorro referencial ${clp(savings)}</span>
      <span>${cfg.text} - Ahorro referencial ${clp(savings)}</span>
    </div>
  </div>`;
}

function comboIncludedItems(combo) {
  const name = `${combo.name || ""} ${combo.modelo || ""}`.toLowerCase();
  const base = combo.modelo || combo.marca || "Equipo principal";
  if (name.includes("gamepad"))
    return [base, "Gamepad de mano", "Proyector de luces LED"];
  if (name.includes("mochila"))
    return [base, "Mochila Happy", "Micas protectoras"];
  if (name.includes("parlante"))
    return [base, "Parlante BT", "Audifonos BT TWS"];
  if (name.includes("audifonos")) return [base, "Audifonos BT", "Tomatodo"];
  if (name.includes("proyector"))
    return [base, "Proyector ENV", "Micas protectoras"];
  if (name.includes("mica")) return [base, "Micas protectoras", "Tomatodo"];
  if (name.includes("drone")) return [base, "Drone mini camara", "Smartwatch"];
  if (name.includes("smartwatch")) return [base, "Smartwatch", "Mochila Happy"];
  return [base, "Accesorio incluido", "Oferta de cierre"];
}

function renderCatalogPager(total, page, pageSize) {
  const totalPages = Math.ceil(total / pageSize);
  if (totalPages <= 1) return "";
  const pages = Array.from({ length: totalPages }, (_, i) => i + 1)
    .map(
      (n) =>
        `<button class="catalog-page-btn ${n === page ? "on" : ""}" onclick="setCatalogPage(${n})">${n}</button>`,
    )
    .join("");
  return `<div class="catalog-pager">
    <button class="catalog-page-arrow" onclick="setCatalogPage(${page - 1})" ${page === 1 ? "disabled" : ""}>Anterior</button>
    <div class="catalog-page-group">${pages}</div>
    <span>Pagina ${page} de ${totalPages} - ${total} productos</span>
    <button class="catalog-page-arrow" onclick="setCatalogPage(${page + 1})" ${page === totalPages ? "disabled" : ""}>Siguiente</button>
  </div>`;
}

function renderCompareSelectionBar() {
  if (!modoComparacion) return "";
  const names = productosComparados.map((p) => p.name).join(" vs ");
  return `<div class="compare-select-bar">
    <div>
      <strong>Comparar telefonos</strong>
      <span>${productosComparados.length}/2 seleccionados${names ? ` - ${names}` : ""}</span>
    </div>
    <button type="button" onclick="cancelarComparacion()">Cancelar</button>
  </div>`;
}

function productImageMarkup(p) {
  if (p.img) {
    return `<img class="prod-img" src="${p.img}" alt="${p.name}" onerror="this.closest('.prod-visual').innerHTML='<div class=&quot;prod-phone-fallback&quot;><b>${p.ico || "CEL"}</b></div>'" />`;
  }
  if (p.cat === "celular") {
    return `<div class="prod-phone-fallback"><b>${p.ico || "CEL"}</b><span>${p.marca || ""}</span></div>`;
  }
  return `<div class="prod-ico">${p.ico}</div>`;
}

function upsellPackVisual(pack) {
  if (!pack?.promoItems?.length) return "";
  return `<div class="upsell-pack-visual">
    ${pack.promoItems
      .map((name) => {
        const item = PRODUCTS.find((p) => p.name === name);
        if (!item) return "";
        const visual = item.img
          ? `<img src="${item.img}" alt="${item.name}" onerror="this.replaceWith(document.createTextNode('${item.ico || "ACC"}'))" />`
          : `<b>${item.ico || "ACC"}</b>`;
        return `<span class="upsell-pack-item" title="${item.name}">${visual}</span>`;
      })
      .join("")}
  </div>`;
}

function assignImei(product) {
  const u = (product.units || []).find((x) => x.st === "disponible");
  if (!u) return null;
  u.st = "reservado";
  return u.imei;
}

function upsellAccessory(id) {
  return PRODUCTS.find((p) => p.id === id);
}

