function upsellAccessorySuggestions(productId) {
  const base = PRODUCTS.find((p) => String(p.id) === String(productId));
  const byType = {
    promo: [607, 601, 613, 614, 604, 610, 615, 606],
    celular: [610, 604, 607, 601, 613, 616, 615, 606],
    combo: [607, 613, 614, 604, 610, 612, 615, 606],
    accesorio: [604, 610, 607, 613, 614, 615, 616, 606],
  };
  const preferred = byType[base?.cat] || byType.celular;
  const offset = Math.abs(Number(productId) || 0) % preferred.length;
  return preferred
    .slice(offset)
    .concat(preferred.slice(0, offset))
    .map((id) => PRODUCTS.find((p) => p.id === id))
    .filter((p) => p && String(p.id) !== String(productId))
    .slice(0, 8);
}

function toggleUpsellAccessories(phoneId) {
  const panel = document.getElementById("upsellSidePanel");
  if (!panel) return;
  const isOpen = panel.style.display !== "none";
  if (isOpen) {
    panel.style.display = "none";
    panel.innerHTML = "";
    return;
  }
  panel.style.display = "";
  renderUpsellAccessoriesPanel(phoneId);
}

function upsellAccessoryList(query = "") {
  const bestSellers = [604, 610, 607, 601, 613, 616, 615, 606, 602, 614, 612, 611];
  const q = String(query || "").trim().toLowerCase();
  return PRODUCTS.filter((p) => p.cat === "accesorio" && Number(p.id) < 900000)
    .sort((a, b) => {
      const ai = bestSellers.indexOf(a.id);
      const bi = bestSellers.indexOf(b.id);
      return (ai === -1 ? 999 : ai) - (bi === -1 ? 999 : bi) || String(a.name).localeCompare(String(b.name));
    })
    .filter((p) => {
      if (!q) return true;
      return [p.name, p.marca, p.modelo, p.ico].filter(Boolean).join(" ").toLowerCase().includes(q);
    });
}

function renderUpsellAccessoriesPanel(phoneId, query = "") {
  const panel = document.getElementById("upsellSidePanel");
  if (!panel) return;
  const accessories = upsellAccessoryList(query);
  const shouldFocusSearch = document.activeElement?.classList?.contains("upsell-accessory-search");
  const caretPos = String(query || "").length;
  panel.innerHTML = `
    <div class="upsell-custom-head">
      <div>
        <strong>Accesorios para agregar</strong>
        <span>Primero se muestran los mas vendidos.</span>
      </div>
    </div>
    <input
      class="upsell-accessory-search"
      value="${String(query || "").replace(/"/g, "&quot;")}"
      placeholder="Buscar accesorio..."
      oninput="renderUpsellAccessoriesPanel(${phoneId}, this.value)"
    />
    <div class="upsell-custom-grid">
      ${accessories
        .map(
          (p) => `<button type="button" class="upsell-custom-item" onclick="addUpsellAccessory(${p.id}, this)">
            <span>${productImageMarkup(p)}</span>
            <strong>${p.name}</strong>
            <em>${clp(p.price)}</em>
            <small>Agregar</small>
          </button>`,
        )
        .join("")}
      ${accessories.length ? "" : '<div class="catalog-empty">No hay accesorios con esa busqueda.</div>'}
    </div>`;
  if (shouldFocusSearch) {
    const search = panel.querySelector(".upsell-accessory-search");
    search?.focus();
    search?.setSelectionRange(caretPos, caretPos);
  }
}

function addUpsellAccessory(id, sourceEl) {
  animateAddToCart(sourceEl, () => {
    addCart(id, { skipUpsell: true, quiet: true });
    const item = PRODUCTS.find((p) => p.id === id);
    renderCart();
    renderCatalog();
    refreshUpsellCupoPreview();
    const basePrice = Number(
      document.getElementById("upsellCupoBasePrice")?.value || 0,
    );
    const exceso = leasingCupoExcess(cartTotal() + basePrice);
    if (exceso > 0) {
      toast(`Excediste tu cupo por ${clp(exceso)}. Retira un extra o cambia de equipo.`, "warn");
      return;
    }
    toast(`${item?.name || "Accesorio"} agregado`);
  });
}

function refreshUpsellCupoPreview() {
  const current = document.querySelector(".upsell-cupo-preview");
  if (!current) return;
  const basePrice = Number(
    document.getElementById("upsellCupoBasePrice")?.value || 0,
  );
  const baseProductId = document.getElementById("upsellCupoBaseProduct")?.value || "";
  const html = renderUpsellCupoPreview(basePrice, baseProductId);
  if (html) current.outerHTML = html;
}

function closeUpsell() {
  document.getElementById("upsellModal").style.display = "none";
  const sidePanel = document.getElementById("upsellSidePanel");
  if (sidePanel) {
    sidePanel.style.display = "none";
    sidePanel.innerHTML = "";
  }
}

function addPromoPackToCart(pack) {
  if (!pack) return;
  const ex = S.cart.find((x) => x.id === pack.id);
  if (ex) ex.qty++;
  else S.cart.push({ ...pack, extraImeis: [] });
}

function animateAddToCart(sourceEl, onDone) {
  const target =
    document.getElementById("cartBadge") ||
    document.getElementById("cartBody") ||
    document.getElementById("cartFoot");
  if (!sourceEl || !target) {
    if (typeof onDone === "function") onDone();
    return;
  }
  const from = sourceEl.getBoundingClientRect();
  const to = target.getBoundingClientRect();
  const clone = sourceEl.cloneNode(true);
  sourceEl.classList.add("is-flying");
  clone.classList.add("cart-fly-clone");
  clone.style.left = `${from.left}px`;
  clone.style.top = `${from.top}px`;
  clone.style.width = `${from.width}px`;
  clone.style.height = `${from.height}px`;
  document.body.appendChild(clone);
  requestAnimationFrame(() => {
    const dx = to.left + to.width / 2 - (from.left + from.width / 2);
    const dy = to.top + to.height / 2 - (from.top + from.height / 2);
    clone.style.transform = `translate(${dx}px, ${dy}px) scale(0.18)`;
    clone.style.opacity = "0.08";
  });
  setTimeout(() => {
    clone.remove();
    sourceEl.classList.remove("is-flying");
    target.classList.add("cart-pulse");
    setTimeout(() => target.classList.remove("cart-pulse"), 620);
    if (typeof onDone === "function") onDone();
  }, 620);
}

function selectUpsellOption(phoneId, optionIndex, sourceEl) {
  const phone = PRODUCTS.find((p) => p.id === phoneId);
  if (!phone) return;
  const option = makeUpsellOptions(phone)[optionIndex];
  S.pendingPhoneColor = selectedUpsellColor();
  animateAddToCart(sourceEl, () => {
    closeUpsell();
    const beforeQty = S.cart
      .filter((x) => x.id === phoneId)
      .reduce((sum, x) => sum + x.qty, 0);
    addCart(phoneId, { skipUpsell: true, quiet: true });
    const afterQty = S.cart
      .filter((x) => x.id === phoneId)
      .reduce((sum, x) => sum + x.qty, 0);
    if (afterQty <= beforeQty) return;
    addPromoPackToCart(option.pack);
    OP.carrito = true;
    renderCart();
    renderCatalog();
    S.pendingPhoneColor = null;
    toast(`${option.title} agregado al carrito`);
  });
}

