var USERS = {
  abarriga: {
    pass: "Chile2026",
    nombre: "Andrés Barriga Romo",
    tienda: "Mall Costanera Center",
    initials: "AB",
  },
  gluengo: {
    pass: "Chile2026",
    nombre: "German Luengo",
    tienda: "Mall Plaza Vespucio",
    initials: "GL",
  },
};

var loginAttempts = 3;
var currentUser = null;

function doLogin() {
  const user = document.getElementById("lgUser").value.trim().toLowerCase();
  const pass = document.getElementById("lgPass").value;
  const errBox = document.getElementById("loginErr");
  const errMsg = document.getElementById("loginErrMsg");
  const lgUserEl = document.getElementById("lgUser");
  const lgPassEl = document.getElementById("lgPass");
  const attInfo = document.getElementById("attemptsInfo");
  const attLeft = document.getElementById("attemptsLeft");

  // Reset estados
  lgUserEl.classList.remove("err");
  lgPassEl.classList.remove("err");

  if (!user || !pass) {
    lgUserEl.classList.toggle("err", !user);
    lgPassEl.classList.toggle("err", !pass);
    errMsg.textContent = "Por favor ingresa usuario y contraseña.";
    errBox.classList.add("show");
    return;
  }

  const userData = USERS?.[user];
  if (userData && userData.pass === pass) {
    // ✅ Login correcto
    currentUser = { username: user, ...userData };
    loginSuccess(currentUser);
  } else {
    // ❌ Login fallido
    loginAttempts--;
    lgUserEl.classList.add("err");
    lgPassEl.classList.add("err");

    if (loginAttempts <= 0) {
      errMsg.textContent =
        "Demasiados intentos fallidos. Cuenta bloqueada temporalmente.";
      errBox.classList.add("show");
      document.getElementById("loginBtn").disabled = true;
      document.getElementById("loginBtn").textContent = "🔒 Cuenta bloqueada";
      attInfo.style.display = "block";
      attLeft.textContent = "0";
      setTimeout(() => {
        loginAttempts = 3;
        document.getElementById("loginBtn").disabled = false;
        document.getElementById("loginBtn").innerHTML =
          "<span>Iniciar sesión</span><span>→</span>";
        attInfo.style.display = "none";
      }, 30000);
    } else {
      errMsg.textContent = `Usuario o contraseña incorrectos.`;
      errBox.classList.add("show");
      attInfo.style.display = "block";
      attLeft.textContent = loginAttempts;
    }
    // Shake animation
    const card = document.querySelector(".login-card");
    card.style.animation = "none";
    card.offsetHeight; // reflow
    card.style.animation = "lgShake .35s ease";
    setTimeout(() => {
      card.style.animation = "";
    }, 400);
  }
}

window.doLogin = doLogin;

function loginSuccess(user) {
  // Ocultar overlay con fade
  const overlay = document.getElementById("loginOverlay");
  overlay.style.transition = "opacity .4s ease";
  overlay.style.opacity = "0";
  setTimeout(() => {
    overlay.style.display = "none";
  }, 400);

  // Actualizar topbar — chip de sesión
  document.getElementById("sessionChip").style.display = "flex";
  document.getElementById("sessionAv").textContent = user.initials;
  document.getElementById("sessionName").textContent = user.nombre;
  document.getElementById("sessionStore").textContent = user.tienda;

  // Actualizar avatar sidebar
  document.getElementById("sbAvatar").textContent = user.initials;

  // Toast de bienvenida
  setTimeout(
    () => toast(`¡Bienvenido, ${user.nombre.split(" ")[0]}! · ${user.tienda}`),
    450,
  );
}

