/* ── HELPERS ───────────────────────────────────── */
function clpFmt(n) {
  return "$ " + Math.round(n).toLocaleString("es-CL");
}
function fechaFmt(s) {
  if (!s) return "—";
  const [y, m, d] = s.split("-");
  return d + "/" + m + "/" + y;
}
function addDays(dateStr, days) {
  const d = new Date(dateStr);
  d.setDate(d.getDate() + days);
  return d.toISOString().split("T")[0];
}
function daysDiff(d1, d2) {
  return Math.round((new Date(d1) - new Date(d2)) / 86400000);
}
function todayStr() {
  return new Date().toISOString().split("T")[0];
}

/* ── GENERAR CARTOLA ──────────────────────────── */
function generarCartola(credito) {
  const {
    entrada,
    capital,
    arrendamiento,
    totalContrato,
    cuotaSemanal,
    plazo,
    fechaOrig,
    pagos,
  } = credito;
  const capPorCuota = Math.round(capital / plazo);
  const arrPorCuota = Math.round(arrendamiento / plazo);
  const cuota = capPorCuota + arrPorCuota;
  const hoy = todayStr();
  const rows = [];

  // Fila 0 - Pago inicial (entrada)
  const pagoEntrada = pagos[0] || null;
  rows.push({
    nro: 0,
    concepto: "Entrada inicial leasing",
    vencimiento: fechaOrig,
    fechaPago: pagoEntrada ? pagoEntrada.fecha : null,
    estado: pagoEntrada ? "PAGADA" : "PENDIENTE",
    capital: 0,
    arrend: 0,
    valorCuota: entrada,
    totalPagado: pagoEntrada ? pagoEntrada.monto : 0,
    saldoCapital: capital,
    saldoContrato: totalContrato,
    diasAtraso: 0,
    obs: "Entrada inicial leasing",
    isEntrada: true,
  });

  let saldoCap = capital;
  let saldoCont = totalContrato;

  for (let i = 1; i <= plazo; i++) {
    const venc = addDays(fechaOrig, i * 7);
    const pago = pagos[i] || null;
    const pagado = !!pago;
    let estado = "PENDIENTE";
    let diasAtraso = 0;
    let obs = "Cuota semanal";

    if (pagado) {
      saldoCap = Math.max(0, saldoCap - capPorCuota);
      saldoCont = Math.max(0, saldoCont - cuota);
      estado = "PAGADA";
      if (pago.fecha > venc) {
        diasAtraso = daysDiff(pago.fecha, venc);
        obs = "Pago con atraso";
      }
    } else {
      if (hoy > venc) {
        diasAtraso = daysDiff(hoy, venc);
        estado = "VENCIDA";
        obs = "Cliente en mora";
      }
    }

    rows.push({
      nro: i,
      concepto: "Cuota semanal N° " + i,
      vencimiento: venc,
      fechaPago: pago ? pago.fecha : null,
      estado,
      capital: capPorCuota,
      arrend: arrPorCuota,
      valorCuota: cuota,
      totalPagado: pago ? pago.monto : 0,
      saldoCapital: pagado ? saldoCap : saldoCap,
      saldoContrato: pagado ? saldoCont : saldoCont,
      diasAtraso,
      obs,
    });
  }
  return rows;
}

